export interface KDropItemData {
  m_iItemID: Int32;
  m_iDropItemUID: Int32;
  m_bLeft: boolean;
  m_fSpeed: Float32;
  m_setGetPossibleUnitUID?: Set<UidType>;
  m_cEnchantLevel?: Int8;
}
export function createKDropItemData(flags?: FlagInput): KDropItemData {
  const f = resolveFlags(flags);
  const obj: KDropItemData = {
    m_iItemID: 0,
    m_iDropItemUID: 0,
    m_bLeft: false,
    m_fSpeed: 0,
  };
  if (Boolean(f.SERV_BATTLE_FIELD_SYSTEM)) obj.m_setGetPossibleUnitUID = new Set<UidType>();
  if (Boolean(f.SERV_ENCHANT_ITEM_DROP_EVENT)) obj.m_cEnchantLevel = 0;
  return obj;
}
export function putKDropItemData(ks: KSerializer, obj: KDropItemData, flags?: FlagInput): boolean {
  const f = resolveFlags(flags);
  if (!(ks.putInt32(obj.m_iItemID))) return false;
  if (!(ks.putInt32(obj.m_iDropItemUID))) return false;
  if (!(ks.putBool(obj.m_bLeft))) return false;
  if (!(ks.putFloat32(obj.m_fSpeed))) return false;
  if (Boolean(f.SERV_BATTLE_FIELD_SYSTEM)) { if (!(ks.putSet((obj.m_setGetPossibleUnitUID ?? new Set<UidType>()), (ks, item: UidType) => ks.putInt64(item)))) return false; }
  if (Boolean(f.SERV_ENCHANT_ITEM_DROP_EVENT)) { if (!(ks.putInt8((obj.m_cEnchantLevel ?? 0)))) return false; }
  return true;
}
export function getKDropItemData(ks: KSerializer, flags?: FlagInput): KDropItemData {
  const f = resolveFlags(flags);
  const obj = createKDropItemData(f);
  obj.m_iItemID = ks.getInt32();
  obj.m_iDropItemUID = ks.getInt32();
  obj.m_bLeft = ks.getBool();
  obj.m_fSpeed = ks.getFloat32();
  if (Boolean(f.SERV_BATTLE_FIELD_SYSTEM)) { obj.m_setGetPossibleUnitUID = ks.getSet<UidType>((ks) => ks.getInt64()); }
  if (Boolean(f.SERV_ENCHANT_ITEM_DROP_EVENT)) { obj.m_cEnchantLevel = ks.getInt8(); }
  return obj;
}

